def candidates(events, links, profiles, acl, depth=2, cap=200):
    out = []
    for e in events:
        for u in links.audience(e.pointer, depth)[:cap]:           # people who own or depend on it
            if acl.can_read(u, e.pointer) and e.kind in profiles[u].watch_kinds:
                out.append(Candidate(u, e.id, "owner" if links.owns(u, e.pointer) else "linked", links.depth(u, e.pointer)))
    return out

ll_score.code:
W = dict(kind=0.4, close=0.3, recent=0.2, seen=0.5)

def score(c, h):
    s = W["kind"]*KIND[c.kind] + W["close"]*(1/(1+c.depth)) + W["recent"]*h.recency(c) - W["seen"]*h.seen(c)
    return max(0.0, min(1.0, s))

def select(cands, h, quota, bar=0.6):
    ranked = sorted(((score(c, h), c) for c in cands), key=lambda x: -x[0])
    return [c for s, c in ranked if s >= bar][:max(0, quota.cap - quota.used)]

