def write_note(gw, ctx, cand, ps):
    out = gw.json(model=SMALL, schema=NoteOut, prompt=render(cand, ps))
    ok = out.citations and all(c in {p.id for p in ps} for c in out.citations) and len(out.text.split()) <= 60
    return Note(out.text, out.citations, out.reason) if ok else template(cand)
